const pptxgen = require('pptxgenjs');
const React = require('react');
const ReactDOMServer = require('react-dom/server');
const sharp = require('sharp');
const { FaBrain, FaCompressAlt, FaMobileAlt, FaListUl, FaExpandArrowsAlt } = require('react-icons/fa');
const { BiChip, BiRun } = require('react-icons/bi');
const { MdOutlineSpeed } = require('react-icons/md');

async function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = await renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

(async () => {
    let pres = new pptxgen();
    pres.layout = 'LAYOUT_16x9'; 
    pres.author = 'Hugging Face & Stanford University';
    pres.title = 'SmolVLM: Redefining Small and Efficient Multimodal Models';

    // Theme Colors (Midnight Executive / Tech Dark)
    const BG_DARK = "0F172A";
    const CARD_BG = "1E293B";
    const ACCENT = "0EA5E9"; // Sky Blue
    const ACCENT_ALT = "10B981"; // Emerald
    const TEXT_PRIMARY = "F8FAFC";
    const TEXT_SECONDARY = "94A3B8";

    // Reusable styles
    const TITLE_STYLE = { x: 0.5, y: 0.5, w: 9, h: 0.8, fontSize: 32, fontFace: 'Arial Black', color: TEXT_PRIMARY, margin: 0 };
    const SUBTITLE_STYLE = { x: 0.5, y: 1.2, w: 9, h: 0.5, fontSize: 18, fontFace: 'Arial', color: ACCENT, margin: 0 };
    const CARD_SHAPE = { fill: { color: CARD_BG }, shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.2 } };

    // Function to add standard background
    function applyMaster(slide) {
        slide.background = { color: BG_DARK };
        slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.15, fill: { color: ACCENT } });
        slide.addText("SmolVLM | Hugging Face & Stanford", { x: 0.5, y: 5.3, w: 9, h: 0.3, fontSize: 10, color: "64748B", align: 'right' });
    }

    // --- Slide 1: Title ---
    let s1 = pres.addSlide();
    s1.background = { color: BG_DARK };
    s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 4, h: 5.625, fill: { color: ACCENT } });

    s1.addText("SmolVLM", { x: 4.5, y: 1.5, w: 5, h: 1.0, fontSize: 54, fontFace: 'Arial Black', color: TEXT_PRIMARY, margin: 0 });
    s1.addText("Redefining Small and Efficient Multimodal Models", { x: 4.5, y: 2.5, w: 5, h: 1.0, fontSize: 22, fontFace: 'Arial', color: ACCENT, margin: 0 });
    s1.addText("Hugging Face & Stanford University", { x: 4.5, y: 4.5, w: 5, h: 0.5, fontSize: 14, fontFace: 'Arial', color: TEXT_SECONDARY, margin: 0 });

    const iconBrain = await iconToBase64Png(FaBrain, "#0F172A", 512);
    s1.addImage({ data: iconBrain, x: 1.0, y: 1.8, w: 2.0, h: 2.0 });

    // --- Slide 2: Problem Motivation ---
    let s2 = pres.addSlide();
    applyMaster(s2);
    s2.addText("Large VLMs Are Powerful but Impractical for Edge Deployment", TITLE_STYLE);

    s2.addShape(pres.shapes.RECTANGLE, { ...CARD_SHAPE, x: 0.5, y: 1.8, w: 4.25, h: 3.2 });
    s2.addText("The Edge Deployment Challenge", { x: 0.7, y: 2.0, w: 3.85, h: 0.5, fontSize: 20, fontFace: 'Arial', color: TEXT_PRIMARY, bold: true });
    s2.addText([
        { text: "State-of-the-art VLMs require massive compute.", options: { bullet: true, breakLine: true } },
        { text: "Cloud dependency adds latency and privacy risks.", options: { bullet: true, breakLine: true } },
        { text: "Mobile hardware lacks GPU memory for multi-gigabyte models.", options: { bullet: true } }
    ], { x: 0.7, y: 2.6, w: 3.85, h: 2, fontSize: 16, fontFace: 'Arial', color: TEXT_SECONDARY, valign: 'top' });

    s2.addShape(pres.shapes.RECTANGLE, { ...CARD_SHAPE, x: 5.25, y: 1.8, w: 4.25, h: 3.2 });
    s2.addText("Memory Footprint Comparison", { x: 5.45, y: 2.0, w: 3.85, h: 0.5, fontSize: 20, fontFace: 'Arial', color: TEXT_PRIMARY, bold: true });

    function addBar(slide, label, val, color, yPos) {
        slide.addText(label, { x: 5.45, y: yPos, w: 1.5, h: 0.3, fontSize: 12, color: TEXT_PRIMARY, margin: 0 });
        let w = Math.max(0.05, (val / 27.7) * 2.0);
        slide.addShape(pres.shapes.RECTANGLE, { x: 7.0, y: yPos, w: w, h: 0.3, fill: { color: color } });
        slide.addText(`${val} GB`, { x: 7.0 + w + 0.1, y: yPos, w: 1, h: 0.3, fontSize: 12, color: TEXT_SECONDARY, margin: 0 });
    }

    addBar(s2, "Molmo-A1B-7B", 27.7, "EF4444", 2.8);
    addBar(s2, "SmolVLM-2.2B", 4.9, ACCENT_ALT, 3.3);
    addBar(s2, "SmolVLM-500M", 1.2, ACCENT, 3.8);
    addBar(s2, "SmolVLM-256M", 0.8, ACCENT, 4.3);


    // --- Slide 3: Architecture ---
    let s3 = pres.addSlide();
    applyMaster(s3);
    s3.addText("SmolVLM Architecture Pipeline", TITLE_STYLE);
    s3.addText("Image Splitting, Pixel Shuffle, and SmolLM2 Backbone", SUBTITLE_STYLE);

    s3.addShape(pres.shapes.RECTANGLE, { ...CARD_SHAPE, x: 0.5, y: 2.0, w: 3.5, h: 3.0 });
